@Component("billingAccount-handler")
@ProcessingGroup("billingAccount-processing-group")
public class BillingAccountEventHandler {
	
	// core constructor
	BillingAccountEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBillingAccountEvent
     */
    @EventHandler
    public void handle( CreateBillingAccountEvent event) {
        entityManager.persist(new BillingAccount(event.getBillingAccountId(), event.getAccountNumber(), event.getBalance(), event.getCustomer(), event.getPolicies(), event.getInvoices(), event.getPayments(), event.getStatus()));
    }

    /*
     * @param	event UpdateBillingAccountEvent
     */
    @EventHandler
    public BillingAccount handle( UpdateBillingAccountEvent event) {
    	entityManager.merge(new BillingAccount(event.getBillingAccountId(), event.getAccountNumber(), event.getBalance(), event.getCustomer(), event.getPolicies(), event.getInvoices(), event.getPayments(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteBillingAccountEvent
     */
    @EventHandler
    public void on( DeleteBillingAccountEvent event) {
    	BillingAccount entity = new BillingAccount();
   
    	// ------------------------------------------
    	// apply the BillingAccountId
    	// ------------------------------------------
    	entity.setBillingAccountId( event.getBillingAccountId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BillingAccountRepository billingAccountEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BillingAccountEventHandler.class.getName());

}
